// "My Voice": the user's own cloned voice, generated by the self-hosted Chatterbox service. Output: WAV.
import { applyProsody, chunkText, encodeWav } from '../audio-utils.js';

const STORE_KEY = 'text2voice.myvoices.v1';
const abortError = () => new DOMException('Cancelled', 'AbortError');
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

/** Reads a PCM16 WAV (what the clone service returns) into mono Float32 samples. */
export function decodeWav(buffer) {
  const view = new DataView(buffer);
  const tag = (o) => String.fromCharCode(view.getUint8(o), view.getUint8(o + 1), view.getUint8(o + 2), view.getUint8(o + 3));
  if (tag(0) !== 'RIFF' || tag(8) !== 'WAVE') throw new Error('Invalid WAV data.');
  let offset = 12;
  let channels = 1;
  let sampleRate = 24000;
  let bits = 16;
  while (offset + 8 <= view.byteLength) {
    const id = tag(offset);
    const size = view.getUint32(offset + 4, true);
    const body = offset + 8;
    if (id === 'fmt ') {
      channels = view.getUint16(body + 2, true);
      sampleRate = view.getUint32(body + 4, true);
      bits = view.getUint16(body + 14, true);
    } else if (id === 'data') {
      if (bits !== 16) throw new Error('Only 16-bit WAV is supported.');
      const frames = Math.floor(Math.min(size, view.byteLength - body) / (2 * channels));
      const samples = new Float32Array(frames);
      for (let i = 0; i < frames; i++) {
        let sum = 0;
        for (let c = 0; c < channels; c++) sum += view.getInt16(body + (i * channels + c) * 2, true);
        samples[i] = sum / channels / 0x8000;
      }
      return { samples, sampleRate };
    }
    offset = body + size + (size % 2);
  }
  throw new Error('WAV has no audio data.');
}

async function errorMessage(res) {
  try {
    return (await res.json()).error || `Request failed (HTTP ${res.status})`;
  } catch {
    return `Request failed (HTTP ${res.status})`;
  }
}

export class MyVoiceEngine {
  id = 'myvoice';
  canDownload = true;
  splitClauses = false;
  defaults = {};

  constructor({ enabled = false } = {}) {
    this.enabled = enabled;
  }

  get supported() {
    return this.enabled;
  }

  /** Voices created in this browser, with their private owner tokens. */
  list() {
    try {
      const list = JSON.parse(localStorage.getItem(STORE_KEY) || '[]');
      return Array.isArray(list) ? list.filter((v) => v && typeof v.id === 'string' && typeof v.token === 'string') : [];
    } catch {
      return [];
    }
  }

  saveList(list) {
    localStorage.setItem(STORE_KEY, JSON.stringify(list));
  }

  async voices() {
    return this.list().map((v) => ({
      id: v.id,
      name: v.name,
      label: v.name,
      title: `Created ${new Date(v.created).toLocaleString()} from ${v.seconds}s of speech`,
      gender: 'unknown',
      lang: 'en-US',
      quality: 0,
    }));
  }

  async status() {
    const res = await fetch('/api/myvoice/status', { cache: 'no-store' });
    if (!res.ok) throw new Error(await errorMessage(res));
    const status = await res.json();
    this.model = status.model;
    return status;
  }

  async create({ wav, name, consentText }) {
    const form = new FormData();
    form.append('audio', wav, 'recording.wav');
    form.append('name', name);
    form.append('consent', 'yes');
    form.append('consent_text', consentText);
    const res = await fetch('/api/myvoice/voices', { method: 'POST', body: form });
    if (!res.ok) throw new Error(await errorMessage(res));
    const voice = await res.json();
    this.saveList([...this.list().filter((v) => v.id !== voice.id), voice]);
    return voice;
  }

  async remove(id) {
    const entry = this.list().find((v) => v.id === id);
    if (entry) {
      const res = await fetch(`/api/myvoice/voices/${id}`, { method: 'DELETE', headers: { 'X-Voice-Token': entry.token } });
      if (!res.ok && res.status !== 404) throw new Error(await errorMessage(res));
    }
    this.saveList(this.list().filter((v) => v.id !== id));
  }

  async render(items, { voice, player = null, signal = null, onProgress = () => {}, expressiveness = 0.5 }) {
    const entry = this.list().find((v) => v.id === voice);
    if (!entry) throw new Error('Create or choose your voice first.');
    const exaggeration = clamp(expressiveness, 0.25, 2);
    // Chatterbox guidance: livelier delivery pairs best with a lower CFG weight.
    const cfgWeight = exaggeration > 0.7 ? 0.3 : 0.5;
    let sampleRate = 24000;
    const chunks = [];
    const total = items.filter((it) => it.type === 'speak').length || 1;
    let done = 0;
    onProgress(0, 'generating');

    for (const item of items) {
      if (signal?.aborted) throw abortError();
      if (item.type === 'pause') {
        chunks.push(new Float32Array(Math.round((item.ms / 1000) * sampleRate)));
        player?.addSilence(item.ms);
        continue;
      }
      for (const piece of chunkText(item.text, 280)) {
        const res = await fetch(`/api/myvoice/voices/${entry.id}/speak`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'X-Voice-Token': entry.token },
          body: JSON.stringify({ text: piece, exaggeration, cfg_weight: cfgWeight }),
          signal,
        });
        if (res.status === 404) throw new Error('This voice no longer exists on the server. Please create it again.');
        if (!res.ok) throw new Error(await errorMessage(res));
        const decoded = decodeWav(await res.arrayBuffer());
        sampleRate = decoded.sampleRate;
        // Chatterbox has no speed/pitch controls, so apply the plan's prosody here.
        const samples = applyProsody(decoded.samples, { pitch: item.pitch || 1, rate: item.rate || 1 }, sampleRate);
        chunks.push(samples);
        player?.addPcm(samples, sampleRate, item.unit);
      }
      onProgress(++done / total, 'generating');
    }
    return { blob: new Blob([encodeWav(chunks, sampleRate)], { type: 'audio/wav' }), ext: 'wav' };
  }
}
